SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(c),'identity',to_jsonb(pg_identify_object('pg_collation'::regclass,c.oid,0)),'owner',pg_get_userbyid(c.collowner)) ORDER BY c.oid),'[]'::jsonb) AS payload FROM pg_collation c WHERE c.collnamespace='public'::regnamespace OR c.oid IN (SELECT attcollation FROM pg_attribute WHERE attrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace))) AS capture